with a as(select * from public.authors where open_library_id=any(array['OL57758A','OL1213378A']::text[]) or id=any(array[654,637]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789029518284','9789029518277','9789023460770','9789023407454','9789023408345','9789023460831']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL719942W','OL15243650W','OL15249098W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['dezaterdagvliegers','uittalloosveelmiljoenen','klaaskwamniet']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['dezaterdagvliegers','uittalloosveelmiljoenen','klaaskwamniet']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987154001 and 987154999),'editions',(select count(*) from public.editions where id between 987254001 and 987254999),'authors',(select count(*) from public.authors where id between 987354001 and 987354999))) as preflight;
